import{_ as o,o as i,c as r,ag as a}from"./chunks/framework.IxO3mcwW.js";const l="/getbiji-docs/images/photo-01.png",s="/getbiji-docs/images/photo-02.png",e="/getbiji-docs/images/photo-03.png",p="/getbiji-docs/images/photo-04.png",n="/getbiji-docs/images/photo-05.png",x=JSON.parse('{"title":"拍照记录","description":"","frontmatter":{},"headers":[],"relativePath":"capture/photo.md","filePath":"capture/photo.md","lastUpdated":1773215704000}'),d={name:"capture/photo.md"};function g(c,t,h,u,m,_){return i(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="拍照记录" tabindex="-1">拍照记录 <a class="header-anchor" href="#拍照记录" aria-label="Permalink to &quot;拍照记录&quot;">​</a></h1><blockquote><p>🖼️ 拍几张，看懂一切——AI 图片笔记把照片秒变条理清晰的笔记！</p></blockquote><p>再也不用在白板、PPT 和信息图之间疯狂截图＋打字；轻轻按下快门，复杂视觉内容瞬间提炼为可编辑、可搜索、结构化的文字。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>课堂 &amp; 培训</strong>：拍下投影 PPT，一秒生成讲义笔记，自动理解核心知识要点</li><li><strong>会议白板</strong>：涂满箭头的 brainstorming 不怕糊；AI 识别流程图关系，转成清单</li><li><strong>读书摘录</strong>：对着纸质书拍几页，立刻得到排版工整的原文摘录</li><li><strong>展览说明牌</strong>：漫步学术年会或博物馆，拍张信息海报就拿到结构化解读</li><li><strong>日常饮食</strong>：把日常每一餐拍进手机，自动分析这一餐的食材和总卡路里</li><li><strong>旅行攻略</strong>：拍机场地图、地铁线路图，AI 自动把站点信息转成可搜的文本</li><li><strong>账单 &amp; 收据</strong>：一键识别金额、日期、商户并分类，月底记账不再翻票根</li><li><strong>教科书里的公式</strong>：包含数学公式、化学方程式，LaTeX 形式输出，可直接贴进论文或作业</li><li><strong>程序代码</strong>：拍下屏幕或书本上的代码片段，AI 自动识别语言并转为可复制的文本格式</li><li><strong>数据表格</strong>：手机对准报表、统计图表一拍，瞬间转换为可编辑的结构化数据</li></ul><h2 id="app-端使用" tabindex="-1">APP 端使用 <a class="header-anchor" href="#app-端使用" aria-label="Permalink to &quot;APP 端使用&quot;">​</a></h2><ol><li><p>打开 App，点击首页底部 + 号，选择「拍照」或「上传图片」</p></li><li><p>首次使用时，授权允许相册使用权限</p></li><li><p>可选多张图片上传，一次可上传10张图</p></li><li><p>选择识图模式「智能总结」、「全文提取」或自定义整理风格</p><ul><li><strong>智能总结</strong>：AI自动选择最佳总结方式，一键把照片&quot;嚼碎&quot;成条理清晰的笔记，90%的场景直接选它就够。</li><li><strong>全文提取</strong>：智能OCR，逐字还原，细节一条不漏，比 OCR 更懂逻辑，把图片里的每一个字、每一条数据，原汁原味且成体系地搬进笔记。</li></ul></li><li><p>笔记生成后，双击文本区域，可对笔记进一步编辑</p></li><li><p>需要分享时，点击右上角「... 更多」</p><ul><li>可以生成笔记海报进行分享</li><li>也可以导出 DOCX / PDF 文件发给好友</li></ul></li></ol><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+l+'" alt="拍照入口" style="width:180px;border-radius:8px;"><img src="'+s+'" alt="选择图片" style="width:180px;border-radius:8px;"><img src="'+e+'" alt="选择模式" style="width:180px;border-radius:8px;"><img src="'+p+'" alt="AI处理" style="width:180px;border-radius:8px;"><img src="'+n+'" alt="笔记结果" style="width:180px;border-radius:8px;"></div>',9)])])}const P=o(d,[["render",g]]);export{x as __pageData,P as default};
